import java.util.*;

public class Main {
    public static void main(String[] args) {
        Todo a = new Todo(1, "Belajar OOP");
        Todo b = new Todo(2, "Beli kopi");
        b.selesaikan();
        System.out.println(a);
        System.out.println(b);
    }
