import java.util.*;

public class Main {
    public static void main(String[] args) {
        Todo a = new Todo(1, "Belajar OOP");
        Todo b = new Todo(2, "Beli kopi");
        b.selesaikan();
        System.out.println(a);
        System.out.println(b);
        Todo c = new Todo(3, "Rapikan meja");
        c.selesaikan();
        System.out.println(c);
        List<Todo> semua = Arrays.asList(a, b, c);
        int n = 0;
        for (Todo t : semua) {
            if (t.isSelesai()) {
                n++;
            }
        }
        System.out.println("Selesai: " + n + " dari " + semua.size());
    }
}

